function rotateK(nums, k) {
  const n = nums.length;
  k = k % n;
  if (k === 0) return nums;
  let temp = nums.slice(0, k);
  for (let i = 0; i < n - k; i++) {
    nums[i] = nums[i + k];
  }
  for (let i = 0; i < k; i++) {
    nums[n - k + i] = temp[i];
  }
  return nums;
}

