function rotateK(nums, k) {
  const n = nums.length;
  k = k % n;
  if (k === 0) return nums;

  function reverse(arr, left, right) {
    while (left < right) {
      let temp = arr[left];
      arr[left] = arr[right];
      arr[right] = temp;
      left++;
      right--;
    }
  }

  reverse(nums, 0, k - 1);
  reverse(nums, k, n - 1);
  reverse(nums, 0, n - 1);
  return nums;
}
